_updateStick(clientX, clientY, cx, cy, maxDist, setKnob) {
  let dx = clientX - cx;
  let dy = clientY - cy;
  const len = Math.hypot(dx, dy);
  if (len > maxDist) { dx = (dx / len) * maxDist; dy = (dy / len) * maxDist; }
  setKnob(dx, dy);
  this.touch.moveX = dx / maxDist;
  this.touch.moveY = dy / maxDist;
}

/* ---------------- public API ---------------- */
update(dt) {
  this._pollGamepad();
