    if (action === 'dash' && (this.pad.buttons[5] || this.pad.buttons[1])) return true;
    if (action === 'lock' && this.pad.buttons[4]) return true;
    if (action === 'interact' && this.pad.buttons[3]) return true;
  }
  return false;
}

consumePressed(action) {
  if (this.pressed.has(action)) {
    this.pressed.delete(action);
    return true;
  }
  return false;
}

getMove() {
  let x = 0, y = 0;
  if (this.enabled) {
    if (this.isDown('right')) x += 1;
    if (this.isDown('left')) x -= 1;
    if (this.isDown('forward')) y += 1;
    if (this.isDown('back')) y -= 1;
    x += this.touch.moveX;
    y += -this.touch.moveY;
    if (this.pad.connected) {
      x += this.pad.axes[0];
      y += -this.pad.axes[1];
    }
  }
  const len = Math.hypot(x, y);
  if (len > 1) { x /= len; y /= len; }
  return { x, y, len: Math.min(1, len) };
}

consumeLook() {
  const out = { x: this.lookX, y: this.lookY };
  this.lookX = 0; this.lookY = 0;
  return out;
}

