633: function groundHeight(world, position) {
634:   // Pick the highest collider top beneath the enemy's feet, with a small
635:   // step allowance so patrolling enemies follow platforms instead of walls.
636:   let best = -Infinity;
637:   for (const c of world.colliders) {
638:     if (!c.active || !c.box) continue;
639:     const b = c.box;
640:     if (position.x < b.min.x - 0.35 || position.x > b.max.x + 0.35) continue;
641:     if (position.z < b.min.z - 0.35 || position.z > b.max.z + 0.35) continue;
642:     if (b.max.y <= position.y + 0.65 && b.max.y > best) best = b.max.y;
643:   }
644:   // Keep the enemy anchored rather than falling forever off a ledge.
645:   if (best === -Infinity) return position.y;
646:   return best;
647: }
