async () => {
  const g = window.__aether; const p = g.player;
  const startY = p.position.y;
  window.dispatchEvent(new KeyboardEvent('keydown', {code:'Space', bubbles:true}));
  let max = startY;
  const t0 = performance.now();
  await new Promise(res => {
    function tick(){ max = Math.max(max, p.position.y); if (performance.now()-t0 < 900) requestAnimationFrame(tick); else res(); }
    requestAnimationFrame(tick);
  });
  window.dispatchEvent(new KeyboardEvent('keyup', {code:'Space', bubbles:true}));
  return {startY, max, height: max-startY};
}
