input.newString:
// Handle Escape directly so it can both pause and resume, even while the
// gameplay input layer is disabled by the pause screen.
window.addEventListener('keydown', (e) => {
  if (e.code !== 'Escape' || e.repeat) return;
  e.preventDefault();
  if (this.state === 'playing') this.pause();
  else if (this.state === 'paused') this.resume();
});

