341:       dir.normalize();
342:       this.velocity.x = dir.x * (opts.knockback ?? 8);
343:       this.velocity.z = dir.z * (opts.knockback ?? 8);
344:       this.velocity.y = opts.up ?? 5.2;
345:     } else {
346:       this.velocity.y = Math.max(this.velocity.y, 4);
347:     }
348:     this.grounded = false;
349:     this.height = HEIGHT;
350:     this.effects.hitSpark(this.center, 0xff7d8a, 18);
351:     this.effects.addShake(0.34, 0.35);
352:     this.callbacks.onDamage?.(amount, this.hp, this.maxHp);
353:     if (this.hp <= 0) this._die();
354:     return true;
355:   }
356: 
357:   _die() {
358:     if (this.dead) return;
359:     this.dead = true;
360:     this.hp = 0;
361:     this.velocity.set(0, 0, 0);
362:     this.attacking = false;
363:     this.ledge = null;
364:     this.callbacks.onDeath?.();
365:   }
366: 
367:   healFull() {
368:     this.hp = this.maxHp;
369:     this.callbacks.onHeal?.(this.hp, this.maxHp);
370:   }
371: 
372:   /* ============================================================
373:      Fixed-step simulation
374:      ============================================================ */
375:   update(dt, input, cameraYaw, aimTarget = null) {
376:     if (this.dead) {
377:       this.time += dt;
378:       return;
379:     }
380:     this.time += dt;
381:     this.aimTarget = aimTarget;
382: 
383:     // timers
384:     this.iframes = Math.max(0, this.iframes - dt);
385:     this.hurtTimer = Math.max(0, this.hurtTimer - dt);
386:     this.dashCooldown = Math.max(0, this.dashCooldown - dt);
387:     this.coyote = Math.max(0, this.coyote - dt);
388:     this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);
389:     this.dashBuffer = Math.max(0, this.dashBuffer - dt);
390:     this.wallJumpLock = Math.max(0, this.wallJumpLock - dt);
391:     this.comboTimer = Math.max(0, this.comboTimer - dt);
392:     this.landTimer = Math.max(0, this.landTimer - dt);
393:     this.attackTimer = Math.max(0, this.attackTimer - dt * 0); // attack consumed below
394: 
395:     // input edges
396:     if (input.consumePressed('jump')) this.jumpBuffer = 0.14;
397:     if (input.consumePressed('dash')) this.dashBuffer = 0.12;
398:     const attackPressed = input.consumePressed('attack');
399:     this.jumpHeld = input.isDown('jump');
400: 
401:     // attack combo input
402:     if (attackPressed) {
403:       if (!this.attacking && this.comboTimer > 0 && this.attackStage < 2 && this.attackStage > 0) {
404:         this._startAttack(this.attackStage + 1);
405:       } else if (!this.attacking) {
406:         this._startAttack(0);
407:       } else if (this.attackStage < 2) {
408:         this.attackQueued = true;
409:       }
410:     }
411: 
412:     // moving platforms carry the player
413:     if (this.grounded && this.standingOn && this.standingOn.platform) {
414:       this.position.add(this.standingOn.platform.delta);
415:     }
416: 
417:     // ledge state
418:     if (this.ledge) {
419:       this._updateLedge(dt);
420:       this._updateAttack(dt);
421:       return;
422:     }
423: 
424:     // dash
425:     if (this.dashTimer > 0) {
426:       this._updateDash(dt);
427:       this._updateAttack(dt);
428:       this._checkHazards();
429:       return;
430:     }
431: 
432:     if (this.dashBuffer > 0 && this.dashCooldown <= 0 && (!this.grounded ? !this.airDashUsed : true)) {
433:       this._startDash(input, cameraYaw);
434:       this._checkHazards();
435:       return;
436:     }
437: 
438:     // movement input relative to camera
439:     const mv = input.getMove();
440:     const forward = V3(-Math.sin(cameraYaw), 0, -Math.cos(cameraYaw));
441:     const right = V3(Math.cos(cameraYaw), 0, -Math.sin(cameraYaw));
442:     const wish = V3().addScaledVector(forward, mv.y).addScaledVector(right, mv.x);
443:     const wishLen = Math.min(1, wish.length());
444:     if (wish.lengthSq() > 0.0001) wish.normalize();
445:     this.lastMove.copy(wish);
446:     const inWater = this.world.inWater(this.position);
447:     const wind = this.world.windAt(this.position);
448:     const speedCap = inWater ? 4.6 : 8.3;
449:     const accel = this.grounded ? 62 : (inWater ? 24 : 34);
450:     const decel = this.grounded ? (inWater ? 10 : 15) : 3.2;
451: 
452:     // slow while attacking / hurt
453:     const control = this.attacking ? 0.28 : (this.hurtTimer > 0 ? 0.12 : 1);
454:     if (wishLen > 0.05) {
455:       const desiredX = wish.x * speedCap * wishLen * control;
456:       const desiredZ = wish.z * speedCap * wishLen * control;
457:       this.velocity.x = damp(this.velocity.x, desiredX, accel * 0.28, dt);
458:       this.velocity.z = damp(this.velocity.z, desiredZ, accel * 0.28, dt);
459:       if (!this.attacking) {
460:         this.targetFacing = Math.atan2(wish.x, wish.z);
461:         if (this.aimTarget) {
462:           this.targetFacing = Math.atan2(this.aimTarget.x - this.position.x, this.aimTarget.z - this.position.z);
463:         }
464:       }
465:     } else {
466:       this.velocity.x = damp(this.velocity.x, 0, decel, dt);
467:       this.velocity.z = damp(this.velocity.z, 0, decel, dt);
468:     }
469: 
470:     // gravity / buoyancy / wind
471:     this.velocity.y -= 32 * dt;
472:     if (inWater) {
473:       this.velocity.y = Math.max(this.velocity.y, -4.5);
474:       if (this.wasJumping) { this.velocity.y = Math.max(this.velocity.y, 5.5); this.wasJumping = false; }
475:     }
476:     if (wind && !this.grounded) {
477:       this.velocity.y += wind.strength * dt * 1.6;
478:       this.velocity.y = Math.min(this.velocity.y, 17);
479:     }
480:     if (this.jumpHeld && this.velocity.y > 0) {
481:       this.velocity.y -= 18 * dt;
482:     } else if (this.velocity.y > 0) {
483:       this.velocity.y -= 16 * dt;
484:     }
485:     this.velocity.y = Math.max(this.velocity.y, -38);
486: 
487:     // jumping
488:     if (this.jumpBuffer > 0) {
489:       if (this.grounded || this.coyote > 0) {
490:         this._jump();
491:       } else if (this.wallContact && this.wallJumpLock <= 0) {
492:         this._wallJump();
493:       } else if (this.jumpsUsed < 2) {
494:         this._doubleJump();
495:       }
496:     }
497: 
498:     // fall through a ledge with down input
499:     if (this.grounded && mv.y < -0.7 && this.standingOn && this.standingOn.kind === 'solid' && this.position.y > 1) {
500:       // only trigger on one-way platforms (none currently) - kept for extensibility
501:     }
502: 
503:     // physics move
504:     this.grounded = false;
505:     this._moveAndCollide(dt);
506:     if (this.grounded) {
507:       this.coyote = 0.11;
508:       this.jumpsUsed = 0;
509:       this.airDashUsed = false;
510:       if (this.velocity.y < -11) {
511:         const impact = clamp(-this.velocity.y / 26, 0.2, 1);
512:         this.landTimer = 0.2;
513:         this.landImpact = impact;
514:         this.effects.burst(this.position.clone().add(V3(0, 0.05, 0)), {
515:           count: 16, speed: 2.6, direction: V3(0, 1, 0), spread: 1.0,
516:           posVar: 0.25, size: 0.18, life: 0.5, gravity: -2, drag: 2.2,
517:           colors: [0xd9c69a, 0xcab98d, 0xffffff],
518:         });
519:         this.callbacks.onLand?.(impact);
520:       }
521:     }
522: 
523:     // wall detection & slide
524:     this._detectWalls();
525:     this.wallSliding = false;
526:     if (!this.grounded && this.wallContact && this.velocity.y < -2.5 && wishLen > 0.2) {
527:       const intoWall = wish.dot(this.wallContact.normal) < -0.25;
528:       if (intoWall && !this.ledge) {
529:         this.wallSliding = true;
530:         this.velocity.y = Math.max(this.velocity.y, -3.2);
531:         if (Math.random() < dt * 18) {
532:           this.effects.spawnWallDust?.(this.position);
533:           this.effects.burst(this.position.clone().add(V3(0, 1.2, 0)).addScaledVector(this.wallContact.normal, -0.35), {
534:             count: 2, speed: 1.2, size: 0.09, life: 0.34, gravity: -1, drag: 3,
535:             colors: [0xd9c9a8, 0xffffff],
536:           });
537:         }
538:       }
539:     }
540: 
541:     // ledge grab
542:     if (!this.grounded && this.velocity.y < -1.2 && !this.attacking && this.wallContact) {
543:       const ledge = this._findLedge(wish);
544:       if (ledge) {
545:         this._grabLedge(ledge);
546:       }
547:     }
548: 
549:     // attack progression
550:     this._updateAttack(dt);
551: 
552:     // footsteps / water splashes
553:     if (this.grounded && this.speed > 2.2) {
554:       this.stepTimer -= dt;
555:       if (this.stepTimer <= 0) {
556:         this.stepTimer = clamp(0.4 - this.speed * 0.027, 0.18, 0.36);
557:         this.effects.footstep(this.position.clone(), this.world.zoneAt(this.position) === 'ruins' ? 0xcabb9a : 0x9fbb7a);
558:         this.callbacks.onStep?.();
559:       }
560:     } else {
561:       this.stepTimer = 0;
562:     }
563:     if (inWater) {
564:       this.splashTimer -= dt;
565:       if (this.splashTimer <= 0 && this.speed > 1.2) {
566:         this.splashTimer = 0.18;
567:         this.effects.splash(this.position.clone().add(V3(0, 0.1, 0)));
568:         this.callbacks.onWater?.();
569:       }
570:     }
571: 
572:     // facing
573:     if (!this.attacking && this.hurtTimer <= 0 && (this.speed > 0.4 || mv.len > 0.1)) {
574:       this.targetFacing = this.aimTarget
575:         ? Math.atan2(this.aimTarget.x - this.position.x, this.aimTarget.z - this.position.z)
576:         : Math.atan2(this.velocity.x, this.velocity.z);
577:     }
578:     if (this.ledge) {
579:       this.targetFacing = Math.atan2(-this.ledge.normal.x, -this.ledge.normal.z);
580:     }
581:     this.facing = angleLerp(this.facing, this.targetFacing, 1 - Math.exp(-16 * dt));
582: 
583:     this._checkHazards();
584: 
585:     if (this.position.y < -50) {
586:       this._die();
587:     }
588:   }
589: 
590:   _jump() {
591:     this.velocity.y = 14.6;
592:     this.grounded = false;
593:     this.coyote = 0;
594:     this.jumpBuffer = 0;
595:     this.jumpsUsed = 1;
596:     this.landTimer = 0;
597:     this.wasJumping = true;
598:     this.effects.burst(this.position.clone(), {
599:       count: 10, speed: 2.4, direction: V3(0, 1, 0), spread: 0.9, posVar: 0.2,
600:       size: 0.14, life: 0.4, gravity: -1, drag: 2.5, colors: [0xd8ccaa, 0xffffff],
601:     });
602:     this.callbacks.onJump?.(false);
603:   }
604: 
605:   _doubleJump() {
606:     this.velocity.y = 13.6;
607:     this.jumpsUsed = 2;
608:     this.jumpBuffer = 0;
609:     this.effects.doubleJump(this.center);
610:     this.callbacks.onDoubleJump?.();
611:   }
612: 
613:   _wallJump() {
614:     const n = this.wallContact.normal;
615:     this.velocity.x = n.x * 10.5;
616:     this.velocity.z = n.z * 10.5;
617:     this.velocity.y = 11.5;
618:     this.jumpsUsed = 1;
619:     this.jumpBuffer = 0;
620:     this.wallJumpLock = 0.25;
621:     this.targetFacing = Math.atan2(n.x, n.z);
622:     this.effects.burst(this.center, {
623:       count: 14, speed: 3.2, size: 0.12, life: 0.38, gravity: -2, drag: 2.4,
624:       colors: [0x8ff7ec, 0xffffff],
625:     });
626:     this.callbacks.onJump?.(true);
627:   }
628: 
629:   _startDash(input, cameraYaw) {
630:     const mv = input.getMove();
631:     let dir;
632:     if (mv.len > 0.15) {
633:       const forward = V3(-Math.sin(cameraYaw), 0, -Math.cos(cameraYaw));
634:       const right = V3(Math.cos(cameraYaw), 0, -Math.sin(cameraYaw));
635:       dir = V3().addScaledVector(forward, mv.y).addScaledVector(right, mv.x).normalize();
636:     } else {
637:       dir = this.forward;
638:     }
639:     this.dashDir.copy(dir);
640:     this.targetFacing = Math.atan2(dir.x, dir.z);
641:     this.dashTimer = 0.22;
642:     this.dashCooldown = 0.72;
643:     this.dashBuffer = 0;
644:     this.velocity.set(dir.x * 25, 0.5, dir.z * 25);
645:     this.iframes = Math.max(this.iframes, 0.28);
646:     if (!this.grounded) this.airDashUsed = true;
647:     this.attacking = false;
648:     this.effects.burst(this.center, {
649:       count: 16, speed: 3, direction: dir.clone().negate(), spread: 0.7,
650:       size: 0.2, life: 0.45, gravity: 0.2, drag: 2.8, colors: [0x8ff7ec, 0xffffff, 0xa8e8ff],
651:     });
652:     this.callbacks.onDash?.();
653:   }
654: 
655:   _updateDash(dt) {
656:     this.dashTimer -= dt;
657:     this.dashTrailTimer -= dt;
658:     this.velocity.y = Math.max(this.velocity.y, -0.2);
659:     this.grounded = false;
660:     this._moveAndCollide(dt);
661:     if (this.dashTrailTimer <= 0) {
662:       this.dashTrailTimer = 0.018;
663:       this.effects.dashTrail(this.center.clone().add(V3(0, 0.2, 0)));
664:     }
665:     if (this.grounded) this.coyote = 0.1;
666:     if (this.dashTimer <= 0) {
667:       this.velocity.x *= 0.42;
668:       this.velocity.z *= 0.42;
669:       this.velocity.y = Math.min(this.velocity.y, 2);
670:     }
671:   }
672: 
673:   _updateLedge(dt) {
674:     if (!this.ledge) return;
675:     this.velocity.set(0, 0, 0);
676:     this.iframes = Math.max(this.iframes, 0.05);
677:     const n = this.ledge.normal;
678:     this.targetFacing = Math.atan2(-n.x, -n.z);
679:     this.facing = angleLerp(this.facing, this.targetFacing, 1 - Math.exp(-20 * dt));
680:     // keep glued
681:     this.position.x = this.ledge.box.max.x + this.radius + 0.02 * (n.x > 0 ? 1 : -1) * 0 - n.x * (this.radius + 0.04);
682:     this.position.z = this.ledge.box.max.z + this.radius + 0.02 * (n.z > 0 ? 1 : -1) * 0 - n.z * (this.radius + 0.04);
683:     this.position.y = this.ledge.box.max.y - 1.62;
684:     if (this.jumpBuffer > 0) {
685:       // climb up
686:       this.position.copy(this.ledge.climbPos);
687:       this.velocity.set(n.x * 1.8, 8.4, n.z * 1.8);
688:       this.ledge = null;
689:       this.jumpBuffer = 0;
690:       this.jumpsUsed = 1;
691:       this.grounded = false;
692:       this.effects.burst(this.center, { count: 12, speed: 2, size: 0.12, life: 0.4, gravity: -3, colors: [0x8ff7ec, 0xffffff] });
693:       this.callbacks.onJump?.(false);
694:       return;
695:     }
696:     if (this.dashBuffer > 0) {
697:       this.velocity.set(n.x * 9, 5, n.z * 9);
698:       this.ledge = null;
699:       this.dashBuffer = 0;
700:       this.iframes = Math.max(this.iframes, 0.2);
701:     }
702:   }
703: 
704:   _findLedge(wish) {
705:     if (!this.wallContact) return null;
706:     const col = this.wallContact.collider;
707:     if (!col || !col.box) return null;
708:     const top = col.box.max.y;
709:     const rel = top - this.position.y;
710:     if (rel < 1.15 || rel > 1.95) return null;
711:     const n = this.wallContact.normal;
712:     if (wish.len > 0.1 && wish.dot(n) > -0.15) return null;
713:     // ensure there's space above
714:     const climbPos = V3(
715:       this.position.x - n.x * (this.radius + 0.08),
716:       top + 0.03,
717:       this.position.z - n.z * (this.radius + 0.08)
718:     );
719:     const test = this._boxAt(climbPos.x, climbPos.y + 0.1, climbPos.z);
720:     for (const c of this.world.colliders) {
721:       if (!c.active) continue;
722:       if (c === col) continue;
723:       if (test.intersectsBox(c.box)) return null;
724:     }
725:     return { box: col.box, normal: n, climbPos };
726:   }
727: 
728:   _grabLedge(ledge) {
729:     this.ledge = ledge;
730:     this.dashTimer = 0;
731:     this.attacking = false;
732:     this.velocity.set(0, 0, 0);
733:     this.wallSliding = false;
734:     this.targetFacing = Math.atan2(-ledge.normal.x, -ledge.normal.z);
735:     this.effects.burst(this.center.clone().add(V3(0, 0.55, 0)), {
736:       count: 10, speed: 1.5, size: 0.1, life: 0.4, gravity: -1, drag: 2.5, colors: [0xffffff, 0xd8ccaa],
737:     });
738:     this.callbacks.onLedge?.();
739:   }
740: 
741:   _startAttack(stage) {
742:     this.attackStage = clamp(stage, 0, 2);
743:     this.attacking = true;
744:     this.attackTimer = 0;
745:     this.attackHitDone = false;
746:     this.attackQueued = false;
747:     this.attackDuration = this.attackStage === 2 ? 0.52 : 0.4;
748:     this.attackHitTime = this.attackStage === 2 ? 0.2 : 0.15;
749:     this.comboTimer = 0.55;
750:     this.sword.visible = true;
751:     if (this.aimTarget) {
752:       this.targetFacing = Math.atan2(this.aimTarget.x - this.position.x, this.aimTarget.z - this.position.z);
753:       this.facing = this.targetFacing;
754:     }
755:     this.velocity.x *= 0.4;
756:     this.velocity.z *= 0.4;
757:     this.callbacks.onAttackStart?.(this.attackStage);
758:   }
759: 
760:   _updateAttack(dt) {
761:     if (!this.attacking) {
762:       this.sword.visible = false;
763:       if (this.attackStage > 0 && this.comboTimer <= 0) this.attackStage = 0;
764:       return;
765:     }
766:     this.attackTimer += dt;
767:     if (!this.attackHitDone && this.attackTimer >= this.attackHitTime) {
768:       this.attackHitDone = true;
769:       const fwd = this.forward;
770:       this.effects.slash(this.position.clone().addScaledVector(fwd, 0.8), this.facing, {
771:         color: this.attackStage === 2 ? 0xffe6a0 : 0x9ffff4,
772:         scale: this.attackStage === 2 ? 1.35 : 1,
773:       });
774:       this.callbacks.onAttackHit?.(this.attackStage, this.position.clone(), this.facing);
775:     }
776:     if (this.attackTimer >= this.attackDuration) {
777:       this.attacking = false;
778:       this.sword.visible = false;
779:       this.comboTimer = 0.38;
780:       if (this.attackQueued && this.attackStage < 2) {
781:         this._startAttack(this.attackStage + 1);
782:       } else if (this.attackStage >= 2) {
783:         this.attackStage = 0;
784:       }
785:     }
786:   }
787: 
788:   _checkHazards() {
789:     if (this.iframes > 0 || this.dead) return;
790:     const box = this._boxAt(this.position.x, this.position.y + 0.15, this.position.z);
791:     const hazard = this.world.hazardAt(box);
792:     if (hazard) {
793:       const center = hazard.box.getCenter(V3());
794:       this.takeDamage(hazard.damage, center, { knockback: hazard.knockback, up: 6.5, iframes: 1.2 });
795:       this.callbacks.onHazard?.(hazard);
796:     }
797:   }
798: 
799:   /* ============================================================
800:      Collision
801:      ============================================================ */
802:   _boxAt(x, y, z) {
803:     const box = this.tmpBox;
804:     box.min.set(x - this.radius, y, z - this.radius);
805:     box.max.set(x + this.radius, y + this.height, z + this.radius);
806:     return box;
807:   }
808: 
809:   _moveAndCollide(dt) {
810:     this.collisionContact.x = 0;
811:     this.collisionContact.z = 0;
812:     const active = this.world.colliders;
813: 
814:     // X
815:     this.position.x += this.velocity.x * dt;
816:     for (let iter = 0; iter < 2; iter++) {
817:       const box = this._boxAt(this.position.x, this.position.y, this.position.z);
818:       let hit = false;
819:       for (const c of active) {
820:         if (!c.active) continue;
821:         if (c.box.max.y <= this.position.y + 0.015) continue; // standing on top, not a wall
822:         if (!box.intersectsBox(c.box)) continue;
823:         // step up small ledges
824:         if (this.grounded && c.box.max.y - this.position.y <= 0.56 && c.box.max.y > this.position.y + 0.02) {
825:           this.position.y = c.box.max.y + 0.015;
826:           this.velocity.y = Math.max(0, this.velocity.y);
827:           this.standingOn = c;
828:           this.grounded = true;
829:           continue;
830:         }
831:         if (this.velocity.x > 0) {
832:           this.position.x = c.box.min.x - this.radius - 0.001;
833:           this.collisionContact.x = 1;
834:         } else if (this.velocity.x < 0) {
835:           this.position.x = c.box.max.x + this.radius + 0.001;
836:           this.collisionContact.x = -1;
837:         } else {
838:           const pc = c.box.getCenter(V3());
839:           this.position.x += this.position.x < pc.x ? -0.02 : 0.02;
840:         }
841:         this.velocity.x = 0;
842:         this._recordWallContact(c, this.collisionContact.x, 0);
843:         hit = true;
844:         break;
845:       }
846:       if (!hit) break;
847:     }
848: 
849:     // Z
850:     this.position.z += this.velocity.z * dt;
851:     for (let iter = 0; iter < 2; iter++) {
